PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS auth(id TEXT PRIMARY KEY,name TEXT NOT NULL,link TEXT,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS attempts(key TEXT PRIMARY KEY,n INTEGER NOT NULL,until_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY,details TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,archived INTEGER NOT NULL DEFAULT 0,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS notes(session TEXT NOT NULL REFERENCES sessions(id),kind TEXT NOT NULL,body TEXT NOT NULL DEFAULT '',version INTEGER NOT NULL DEFAULT 1,PRIMARY KEY(session,kind));
CREATE TABLE IF NOT EXISTS assets(id TEXT PRIMARY KEY,name TEXT NOT NULL,mime TEXT NOT NULL,ratio REAL NOT NULL,contributor TEXT NOT NULL,tags TEXT NOT NULL DEFAULT '',created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS items(id TEXT PRIMARY KEY,session TEXT NOT NULL REFERENCES sessions(id),asset TEXT REFERENCES assets(id),kind TEXT NOT NULL DEFAULT 'image',body TEXT NOT NULL DEFAULT '',transform TEXT NOT NULL,final INTEGER NOT NULL DEFAULT 0,version INTEGER NOT NULL DEFAULT 1,created INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS items_session ON items(session);
CREATE TABLE IF NOT EXISTS likes(item TEXT NOT NULL REFERENCES items(id),person TEXT NOT NULL,name TEXT NOT NULL,PRIMARY KEY(item,person));
CREATE TABLE IF NOT EXISTS comments(id TEXT PRIMARY KEY,item TEXT NOT NULL REFERENCES items(id),name TEXT NOT NULL,body TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS links(token TEXT PRIMARY KEY,session TEXT NOT NULL REFERENCES sessions(id),role TEXT NOT NULL,pin TEXT,active INTEGER NOT NULL DEFAULT 1,created INTEGER NOT NULL);
